<?php require_once __DIR__.'/../lib/branding.php';$brand=organizationBrand();$brandName=(string)$brand['name'];$titles=['setup'=>'Create your workspace','login'=>'Welcome back','forgot'=>'Reset your password','reset'=>'Choose a new password'];$subtitles=['setup'=>'Create the first administrator for this '.$brandName.' installation.','login'=>'Sign in to continue to your recruiter workspace.','forgot'=>'Enter your account email to create a secure reset link.','reset'=>'Use at least eight characters for your new password.'];?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars(brandedPageTitle($titles[$mode],$brand))?></title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="assets/app.css"><style>.auth-page{min-height:100vh;display:grid;grid-template-columns:1.05fr .95fr;background:var(--bg)}.auth-visual{padding:42px;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#6942f4,#8a6aff);color:#fff;position:relative;overflow:hidden}.auth-visual:after{content:"";position:absolute;width:520px;height:520px;border:1px solid rgba(255,255,255,.17);border-radius:50%;right:-190px;bottom:-200px;box-shadow:0 0 0 70px rgba(255,255,255,.04),0 0 0 140px rgba(255,255,255,.025)}.auth-brand{display:flex;align-items:center;gap:11px;font-size:17px;font-weight:700;z-index:1}.auth-brand i{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;background:rgba(255,255,255,.16)}.auth-copy{max-width:530px;z-index:1}.auth-copy h2{font-size:clamp(34px,4vw,58px);line-height:1.02;letter-spacing:-.05em;margin:0 0 18px}.auth-copy p{color:rgba(255,255,255,.76);line-height:1.7}.auth-points{display:flex;gap:18px;flex-wrap:wrap;font-size:10px;color:rgba(255,255,255,.78)}.auth-wrap{display:grid;place-items:center;padding:32px}.auth-card{width:min(420px,100%);background:#fff;border:1px solid var(--line);border-radius:22px;padding:30px;box-shadow:var(--shadow)}.auth-logo{width:45px;height:45px;border-radius:14px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-size:17px}.auth-card h1{font-size:26px;letter-spacing:-.04em;margin:19px 0 6px}.auth-card>p{color:var(--muted);font-size:11px;line-height:1.6;margin:0 0 18px}.auth-card label{display:flex;justify-content:space-between;margin:13px 0 6px;font-size:9px;font-weight:700;color:#5d6170}.auth-card .btn{width:100%;margin-top:18px}.auth-links{display:flex;justify-content:space-between;margin-top:15px;color:var(--primary);font-size:10px}.message{padding:10px;border-radius:10px;font-size:10px;margin-bottom:12px}.message.error{background:#fff1f3;color:var(--danger)}.message.success{background:var(--green-soft);color:var(--green)}.reset-link{display:block;margin-top:8px;word-break:break-all;font-size:9px;font-weight:600}.password-wrap{position:relative}.password-wrap .control{padding-right:40px}.toggle{position:absolute;right:4px;top:4px;width:30px;height:30px;border:0;background:transparent;color:var(--muted)}@media(max-width:800px){.auth-page{grid-template-columns:1fr}.auth-visual{display:none}.auth-wrap{padding:18px}}</style></head><body><main class="auth-page"><section class="auth-visual"><div class="auth-brand"><i class="fa-solid fa-cube"></i><?=htmlspecialchars($brandName)?></div><div class="auth-copy"><h2>Hiring intelligence, without the noise.</h2><p>Explainable scoring, structured experience timelines and recruiter-controlled candidate workflows in one secure workspace.</p></div><div class="auth-points"><span><i class="fa-solid fa-shield-halved"></i> Secure workspace</span><span><i class="fa-solid fa-chart-simple"></i> Explainable evidence</span><span><i class="fa-solid fa-users"></i> Persistent pipeline</span></div></section><section class="auth-wrap"><form class="auth-card" method="post"><div class="auth-logo"><i class="fa-solid <?=$mode==='login'?'fa-arrow-right-to-bracket':($mode==='setup'?'fa-user-shield':'fa-key')?>"></i></div><h1><?=htmlspecialchars($titles[$mode])?></h1><p><?=htmlspecialchars($subtitles[$mode])?></p><?php if(!empty($error)):?><div class="message error"><i class="fa-solid fa-circle-exclamation"></i> <?=htmlspecialchars($error)?></div><?php endif?><?php if(!empty($notice)):?><div class="message success"><i class="fa-solid fa-circle-check"></i> <?=htmlspecialchars($notice)?><?php if(!empty($resetLink)):?><a class="reset-link" href="<?=htmlspecialchars($resetLink)?>"><?=htmlspecialchars($resetLink)?></a><?php endif?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrfToken()?>"><?php if($mode==='reset'):?><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><?php endif?><?php if($mode==='setup'):?><label>Name</label><input class="control" name="name" required autocomplete="name"><?php endif?><?php if(in_array($mode,['setup','login','forgot'],true)):?><label>Email</label><input class="control" type="email" name="email" required autocomplete="email"><?php endif?><?php if(in_array($mode,['setup','login','reset'],true)):?><label>Password</label><div class="password-wrap"><input class="control password" type="password" name="password" minlength="8" required autocomplete="<?=$mode==='login'?'current-password':'new-password'?>"><button class="toggle" type="button" aria-label="Show password"><i class="fa-regular fa-eye"></i></button></div><?php endif?><?php if($mode==='reset'):?><label>Confirm password</label><input class="control" type="password" name="confirm_password" minlength="8" required autocomplete="new-password"><?php endif?><button class="btn btn-primary"><?=['setup'=>'Create admin','login'=>'Sign in','forgot'=>'Create reset link','reset'=>'Update password'][$mode]?></button><div class="auth-links"><?php if($mode==='login'):?><a href="forgot_password.php">Forgot password?</a><?php endif?><?php if(in_array($mode,['forgot','reset'],true)):?><a href="login.php">Back to login</a><?php endif?></div></form></section></main><script>document.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>{const i=b.parentElement.querySelector('input');i.type=i.type==='password'?'text':'password';b.querySelector('i').className=i.type==='password'?'fa-regular fa-eye':'fa-regular fa-eye-slash'})</script></body></html>
